39→  return {
40→    title: event.title,
41→    description,
42→    openGraph: {
43→      title: event.title,
44→      description,
45→      ...(event.thumbnail && {
46→        images: [{ url: event.thumbnail }],
47→      }),
48→    },
49→  };
