 1→export interface ParsedSection {
 2→  label: string;
 3→  content: string;
 4→}
 5→
 6→/**
 7→ * Markdownの見出し形式（## または ###）でdescriptionをセクションに分割する
 8→ * 見出しがない場合は全体を「内容」として返す
 9→ */
10→export function parseEventDescription(
11→  description: string | null | undefined,
12→): ParsedSection[] {
13→  if (!description) {
14→    return [];
15→  }
16→
17→  const lines = description.split("\n");
18→  const sections: ParsedSection[] = [];
19→  let currentLabel: string | null = null;
20→  let currentContent: string[] = [];
21→
22→  for (const line of lines) {
23→    // ## または ### で始まる行を見出しとして検出
24→    const headingMatch = line.match(/^#{2,3}\s+(.+)$/);
25→
26→    if (headingMatch) {
27→      // 前のセクションを保存
28→      if (currentLabel !== null) {
29→        sections.push({
30→          label: currentLabel,
31→          content: currentContent.join("\n").trim(),
32→        });
33→      }
34→      currentLabel = headingMatch[1].trim();
35→      currentContent = [];
36→    } else {
37→      currentContent.push(line);
38→    }
39→  }
40→
41→  // 最後のセクションを保存
42→  if (currentLabel !== null) {
43→    sections.push({
44→      label: currentLabel,
45→      content: currentContent.join("\n").trim(),
46→    });
47→  }
48→
49→  // 見出しがなかった場合は全体を「内容」として返す
50→  if (sections.length === 0 && description.trim()) {
51→    return [{ label: "内容", content: description.trim() }];
52→  }
53→
54→  // 空のコンテンツを持つセクションを除外
55→  return sections.filter((section) => section.content.length > 0);
56→}
