  1→import { DateTime } from "luxon";
  2→
  3→const DATE_FORMATS = {
  4→  FULL_DATE_JP: "yyyy年MM月dd日(EEE) HH:mm",
  5→  DATE_JP: "yyyy年MM月dd日",
  6→  TIME: "HH:mm",
  7→} as const;
  8→
  9→type DateFormatKey = keyof typeof DATE_FORMATS;
 10→
 11→export const APP_TIMEZONE = "Asia/Tokyo";
 12→const DATE_PLACEHOLDER_TEXT = "日時不明";
 13→const TIME_PLACEHOLDER_TEXT = "時刻未定";
 14→const LOCALE = "ja";
 15→
 16→/**
 17→ * タイムゾーンを固定したDateTimeオブジェクトを作成する
 18→ * trueを返すことで、isValidを強制する
 19→ */
 20→function dateTimeFromISO(dateString: string): DateTime<true> {
 21→  return DateTime.fromISO(dateString)
 22→    .setZone(APP_TIMEZONE)
 23→    .setLocale(LOCALE) as DateTime<true>;
 24→}
 25→
 26→/**
 27→ * ISO形式の日時文字列から指定されたフォーマットで文字列を返す
 28→ *
 29→ * @param dateString - ISO8601形式の日時文字列
 30→ * @param format - FORMATSのキーまたはカスタムフォーマット文字列
 31→ * @returns フォーマットされた日時文字列
 32→ */
 33→function format(dateString: string, format: DateFormatKey | string): string {
 34→  try {
 35→    const dt = dateTimeFromISO(dateString);
 36→
 37→    if (!dt.isValid) {
 38→      console.warn(`Invalid date string: ${dateString}`);
 39→      return DATE_PLACEHOLDER_TEXT;
 40→    }
 41→
 42→    const formatString =
 43→      format in DATE_FORMATS ? DATE_FORMATS[format as DateFormatKey] : format;
 44→
 45→    return dt.toFormat(formatString);
 46→  } catch (error) {
 47→    console.error("Date formatting error:", error);
 48→    return DATE_PLACEHOLDER_TEXT;
 49→  }
 50→}
 51→
 52→/**
 53→ * 日本語形式の日付文字列を返す (shorthand)
 54→ */
 55→function formatDateJP(dateString: string): string {
 56→  return format(dateString, DATE_FORMATS.DATE_JP);
 57→}
 58→
 59→function formatDateTimeJP(dateString: string): string {
 60→  return format(dateString, DATE_FORMATS.FULL_DATE_JP);
 61→}
 62→/**
 63→ * 時刻文字列を返す (shorthand)
 64→ */
 65→function formatTime(dateString: string): string {
 66→  if (!hasTimeInfo(dateString)) {
 67→    console.warn(`No time information in date string: ${dateString}`);
 68→    return TIME_PLACEHOLDER_TEXT;
 69→  }
 70→  return format(dateString, DATE_FORMATS.TIME);
 71→}
 72→
 73→/**
 74→ * ISO形式の文字列に時刻情報が含まれているかチェック
 75→ */
 76→function hasTimeInfo(dateString: string): boolean {
 77→  return dateString.includes("T");
 78→}
 79→
 80→/**
 81→ * MM/DD形式で日付を返す
 82→ * 例: "12/25"
 83→ */
 84→function formatMonthDayOnly(dateString: string): string {
 85→  const dt = parseDateTimeSafely(dateString);
 86→  if (!dt) return DATE_PLACEHOLDER_TEXT;
 87→
 88→  const month = dt.month.toString().padStart(2, "0");
 89→  const day = dt.day.toString().padStart(2, "0");
 90→  return `${month}/${day}`;
 91→}
 92→
 93→/**
 94→ * 曜日を短縮形で返す
 95→ * 例: "Sat."
 96→ */
 97→function formatDayOfWeek(dateString: string): string {
 98→  const dt = parseDateTimeSafely(dateString);
 99→
100→  if (!dt) return "";
101→  return `${dt.setLocale("en").toFormat("EEE")}.`;
102→}
103→
104→/**
105→ * 日付文字列を安全にパースする共通関数
106→ */
107→function parseDateTimeSafely(dateString: string): DateTime | undefined {
108→  try {
109→    const dt = dateTimeFromISO(dateString);
110→    if (!dt.isValid) {
111→      console.warn(`Invalid date string: ${dateString}`);
112→      return undefined;
113→    }
114→    return dt;
115→  } catch (error) {
116→    console.error("Date formatting error:", error);
117→    return undefined;
118→  }
119→}
120→
121→/**
122→ * 指定月の金・土・日を取得
123→ */
124→function getWeekendDatesInMonth(
125→  year: number,
126→  month: number,
127→): Array<{ date: string; dayOfWeek: string }> {
128→  const dates: Array<{ date: string; dayOfWeek: string }> = [];
129→  const dt = DateTime.fromObject(
130→    { year, month },
131→    { zone: APP_TIMEZONE, locale: LOCALE },
132→  );
133→
134→  if (!dt.isValid) {
135→    console.warn(`Invalid year/month: ${year}/${month}`);
136→    return dates;
137→  }
138→
139→  const daysInMonth = dt.daysInMonth || 0;
140→  for (let day = 1; day <= daysInMonth; day++) {
141→    const currentDate = DateTime.fromObject(
142→      { year, month, day },
143→      { zone: APP_TIMEZONE, locale: LOCALE },
144→    );
145→
146→    if (!currentDate.isValid) continue;
147→
148→    const weekday = currentDate.weekday;
149→    if (weekday === 5 || weekday === 6 || weekday === 7) {
150→      const dateStr = currentDate.toISODate();
151→      if (dateStr) {
152→        dates.push({
153→          date: dateStr,
154→          dayOfWeek: currentDate.toFormat("EEE"),
155→        });
156→      }
157→    }
158→  }
159→
160→  return dates;
161→}
162→
163→/**
164→ * 月名を取得
165→ */
166→function getMonthName(
167→  year: number,
168→  month: number,
169→  locale: "ja" | "en" = "en",
170→): string {
171→  try {
172→    const dt = DateTime.fromObject(
173→      { year, month },
174→      { zone: APP_TIMEZONE, locale: locale === "ja" ? "ja" : "en" },
175→    );
176→
177→    if (!dt.isValid) {
178→      console.warn(`Invalid year/month: ${year}/${month}`);
179→      return "";
180→    }
181→
182→    if (locale === "ja") {
183→      return dt.toFormat("M月");
184→    }
185→    return dt.toFormat("MMMM");
186→  } catch (error) {
187→    console.error("Month name formatting error:", error);
188→    return "";
189→  }
190→}
191→
192→/**
193→ * 曜日に応じた色クラスを取得
194→ * 土曜日(6): darkBlue, 日曜日(7): red, その他: 空文字列
195→ *
196→ * CSS変数 --color-day-saturday / --color-day-sunday を使用
197→ * (Tailwind v4 は動的クラス名を検出できないため静的クラス名を使用)
198→ */
199→function getDayOfWeekColorClass(dateString: string): string {
200→  const dt = dateTimeFromISO(dateString);
201→  if (!dt.isValid) return "";
202→
203→  const weekday = dt.weekday;
204→  if (weekday < 6) return "";
205→
206→  return weekday === 6 ? "text-day-saturday" : "text-day-sunday";
207→}
208→
209→// =============================================================================
210→// Calendar Adapter Functions (ISO ↔ Date 変換)
211→// =============================================================================
212→
213→/**
214→ * ISO文字列をDateオブジェクトに変換 (Calendar用)
215→ * APP_TIMEZONE (Asia/Tokyo) として解釈
216→ */
217→function isoToDate(isoString: string | undefined): Date | undefined {
218→  if (!isoString) return undefined;
219→
220→  const dt = dateTimeFromISO(isoString);
221→  if (!dt.isValid) return undefined;
222→
223→  return dt.toJSDate();
224→}
225→
226→/**
227→ * DateオブジェクトをISO文字列に変換 (YYYY-MM-DD形式)
228→ * APP_TIMEZONE (Asia/Tokyo) として解釈
229→ */
230→function dateToIso(date: Date | undefined): string | undefined {
231→  if (!date) return undefined;
232→
233→  const dt = DateTime.fromJSDate(date, { zone: APP_TIMEZONE });
234→  if (!dt.isValid) return undefined;
235→
236→  return dt.toISODate() ?? undefined;
237→}
238→
239→/**
240→ * DateオブジェクトをフルISO8601文字列に変換
241→ * DB (UTC) からの変換用
242→ */
243→function dateToIsoFull(date: Date): string {
244→  const dt = DateTime.fromJSDate(date, { zone: "utc" });
245→  return dt.toISO() ?? "";
246→}
247→
248→/**
249→ * ISO文字列配列をDateオブジェクト配列に変換 (multiple mode用)
250→ */
251→function isoArrayToDateArray(
252→  isoStrings: string[] | undefined,
253→): Date[] | undefined {
254→  if (!isoStrings) return undefined;
255→
256→  return isoStrings
257→    .map((iso) => isoToDate(iso))
258→    .filter((date): date is Date => date !== undefined);
259→}
260→
261→/**
262→ * Dateオブジェクト配列をISO文字列配列に変換 (multiple mode用)
263→ */
264→function dateArrayToIsoArray(dates: Date[] | undefined): string[] | undefined {
265→  if (!dates) return undefined;
266→
267→  return dates
268→    .map((date) => dateToIso(date))
269→    .filter((iso): iso is string => iso !== undefined);
270→}
271→
272→export {
273→  formatDateJP,
274→  formatDateTimeJP,
275→  formatTime,
276→  formatMonthDayOnly,
277→  formatDayOfWeek,
278→  getWeekendDatesInMonth,
279→  getMonthName,
280→  getDayOfWeekColorClass,
281→  isoToDate,
282→  dateToIso,
283→  dateToIsoFull,
284→  isoArrayToDateArray,
285→  dateArrayToIsoArray,
286→  dateTimeFromISO,
287→};
