  3→import { cn } from "@/utils/cn";
  4→import { parseTextWithUrls } from "@/utils/linkify";
  5→import { parseEventDescription } from "@/utils/parseEventDescription";
  6→
  7→export interface EventDescriptionProps {
  8→  description?: string;
  9→  className?: string;
 10→}
 11→
 12→export function EventDescription({
 13→  description,
 14→  className,
 15→}: EventDescriptionProps) {
 16→  const sections = parseEventDescription(description);
 17→
 18→  if (sections.length === 0) {
 19→    return null;
 20→  }
 21→
 22→  return (
 23→    <div className={cn("space-y-6", className)}>
 24→      {sections.map((section) => (
 25→        <EventDetailField
 26→          key={section.label}
 27→          label={section.label}
 28→          content={section.content}
 29→        />
 30→      ))}
 31→    </div>
 32→  );
 33→}
