 35→interface EventDetailFieldProps {
 36→  label: string;
 37→  content: string;
 38→}
 39→
 40→function EventDetailField({ label, content }: EventDetailFieldProps) {
 41→  return (
 42→    <div className="pt-4">
 43→      <h2
 44→        className={cn(
 45→          "font-display font-semibold",
 46→          "text-lg md:text-xl",
 47→          "mb-3",
 48→        )}
 49→      >
 50→        {label}
 51→      </h2>
 52→      <div
 53→        className={cn(
 54→          "font-display text-sm md:text-base",
 55→          "leading-relaxed",
 56→          "whitespace-pre-wrap",
 57→        )}
 58→      >
 59→        <LinkifiedText text={content} />
 60→      </div>
 61→    </div>
 62→  );
 63→}
 64→
 65→interface LinkifiedTextProps {
 66→  text: string;
 67→}
 68→
 69→function LinkifiedText({ text }: LinkifiedTextProps) {
 70→  const segments = parseTextWithUrls(text);
 71→
 72→  return (
 73→    <>
 74→      {segments.map((segment) => {
 75→        const keyContent =
 76→          segment.type === "url"
 77→            ? segment.content
 78→            : segment.content.slice(0, 20);
 79→        const key = `${segment.type}-${keyContent}`;
 80→
 81→        if (segment.type === "url") {
 82→          return (
 83→            <a
 84→              key={key}
 85→              href={segment.content}
 86→              target="_blank"
 87→              rel="noopener noreferrer"
 88→              className={cn(
 89→                "text-soypoy-accent underline",
 90→                "hover:text-soypoy-accent/80",
 91→                "transition-colors",
 92→                "break-all",
 93→              )}
 94→            >
 95→              {segment.content}
 96→            </a>
 97→          );
 98→        }
 99→        return <span key={key}>{segment.content}</span>;
100→      })}
101→    </>
102→  );
103→}
