13→export function EventDate({ date, className }: EventDateProps) {
14→  return (
15→    <div className={cn(className)}>
16→      <time
17→        className={cn(
18→          "font-medium",
19→          "text-5xl md:text-6xl",
20→          "leading-none",
21→          "block",
22→        )}
