## Implementation Plan: Phase 2 -- Structured Event Fields UI + Admin Preview

### Overview

This plan covers four workstreams:
1. User-facing event detail page refactoring to show structured fields
2. EventListItem price display fix
3. Admin detail page tab navigation with Web Preview and Instagram Preview
4. Instagram caption text generator utility

---

### 1. Instagram Caption Generator Utility

**New file: `/Users/masanao/Dev/soypoy-potal/src/utils/instagramCaption.ts`**

This is a pure utility function with no React dependency, making it easily testable and reusable across admin preview components and the copyable text tab.

```typescript
import type { EventEntity } from "@/domain/entities";
import type { EventType } from "@/domain/entities/event/eventType";
import { formatDateJP } from "@/utils/date";

/**
 * EventType に対応する絵文字マッピング
 */
const EVENT_TYPE_EMOJI: Record<EventType, string> = {
  art: "\u{1F3A8}",       // palette
  comedy: "\u{1F923}",    // rolling on floor laughing
  dance: "\u{1F483}",     // dancer
  design: "\u{270F}\uFE0F", // pencil
  impro: "\u{1F3AD}",     // performing arts
  impro_kanji: "\u{1F3AD}",
  movie: "\u{1F3AC}",     // clapper board
  music: "\u{1F3B5}",     // musical note
  photo: "\u{1F4F7}",     // camera
  talk: "\u{1F4AC}",      // speech balloon
  theater: "\u{1F3AD}",   // performing arts
  workshop: "\u{1F528}",  // hammer
  other: "\u{2728}",      // sparkles
};

/**
 * イベントエンティティからInstagramキャプションテキストを生成する
 */
export function generateInstagramCaption(event: EventEntity): string {
  const lines: string[] = [];

  // タイトル (with event type emoji)
  const emoji = EVENT_TYPE_EMOJI[event.type] ?? "\u{2728}";
  lines.push(`${emoji} ${event.title}`);
  lines.push("");

  // 日時
  lines.push(`\u{1F4C5} ${formatDateJP(event.date)}`);
  lines.push(`\u{1F6AA} OPEN ${event.openTime} / START ${event.startTime}`);
  lines.push("\u{1F4CD} SOY-POY");
  lines.push("");

  // 料金
  if (event.pricing && event.pricing.length > 0) {
    lines.push("\u{1F4B0} 料金");
    for (const tier of event.pricing) {
      const line = `${tier.label} ¥${tier.amount.toLocaleString()}`;
      lines.push(tier.note ? `${line}（${tier.note}）` : line);
    }
    lines.push("");
  }

  // 出演者
  if (event.performers && event.performers.length > 0) {
    lines.push("\u{1F3A4} 出演");
    for (const performer of event.performers) {
      if (performer.instagramHandle) {
        const rolePart = performer.role ? `（${performer.role}）` : "";
        lines.push(`@${performer.instagramHandle}${rolePart}`);
      } else {
        const rolePart = performer.role ? `（${performer.role}）` : "";
        lines.push(`${performer.name}${rolePart}`);
      }
    }
    lines.push("");
  }

  // 説明（概要）
  if (event.description) {
    lines.push(event.description);
    lines.push("");
  }

  // ハッシュタグ
  if (event.hashtags && event.hashtags.length > 0) {
    lines.push(event.hashtags.map((tag) => `#${tag}`).join(" "));
  }

  return lines.join("\n").trim();
}
```

**Design decisions:**
- Pure function, no side effects, framework-agnostic -- could live in `domain/` conceptually, but placed in `utils/` following the existing project convention where formatting utilities live.
- Uses the same `formatDateJP` utility already present in the codebase.
- The EventType-to-emoji mapping is defined in this file because it serves a specific formatting purpose. The BubleLabel component's `variantMap` serves a different purpose (label images) and should remain separate.

